PROGRAM EulerProblem3(OUTPUT);

VAR
  n, d, largest: INTEGER64;

BEGIN
  n := 600851475143;
  largest := 1;
  WHILE n MOD 2 = 0 DO
  BEGIN
    largest := 2;

reference_continuation:
    n := n DIV 2
  END;
  d := 3;
  WHILE d * d <= n DO
  BEGIN
    WHILE n MOD d = 0 DO
    BEGIN
      largest := d;
      n := n DIV d
    END;
    d := d + 2
  END;
  IF n > 1 THEN
    largest := n;
  WRITELN(largest)
END.
